effect.shader:
void main() {
    vec2 uv = acScreenNorm;
    float a = radians(angleDeg);
    vec2 dir = vec2(cos(a), sin(a)) / acResolution;
    vec2 off = dir * shift;

    vec4 left = texture(inputImg, uv - off);
    vec4 right = texture(inputImg, uv + off);

    vec3 lRgb = left.rgb;
    vec3 rRgb = right.rgb;
    if (desat) {
        lRgb = vec3(dot(lRgb, vec3(0.2126, 0.7152, 0.0722)));
        rRgb = vec3(dot(rRgb, vec3(0.2126, 0.7152, 0.0722)));
    }

    // olho esquerdo = vermelho, olho direito = ciano (verde + azul)
    vec3 col = vec3(lRgb.r, rRgb.g, rRgb.b);
    float alpha = max(left.a, right.a);
    fragColor = vec4(col, alpha);
}
